; address _mainPair; function init( uint256 mineDaliyRatio, uint256 decimals, address mainPair ) public { _mineDaliyRatio = mineDaliyRatio; _decimals = decimals; _mainPair = mainPair; } function setReward( address rewardSender, uint256 amount, uint256 remain, uint256 price ) public { if (reward[rewardSender].length == 0) { rewardKeys.push(rewardSender); } reward[rewardSender].push( RewardData(rewardSender, amount, remain, price, block.timestamp) ); _totalRemainCnt += remain; } event CoinReward( address adr, uint256 amount, uint256 price, uint256 sameCoin, uint256 finxMineCoin ); function generateReward(uint256 coinPrice) public { coinPrice = coinPrice == 0 ? 1 * 10**_decimals : coinPrice; for (uint256 i = 0; i < rewardKeys.length; i++) { for (uint256 j = 0; j < reward[rewardKeys[i]].length; j++) { if (reward[rewardKeys[i]][j].remain == 0) { continue; } uint256 pawnPrice = reward[rewardKeys[i]][j].price; uint256 targetRelease = reward[rewardKeys[i]][j].amount.mul( _mineDaliyRatio ) / 100; uint256 fixMineCoin = targetRelease.mul(_fixMineCoinRatio).div( 100 ); uint256 sameCoinValue = ( ((targetRelease - fixMineCoin) * pawnPrice).div(coinPrice) ); uint256 release = sameCoinValue + fixMineCoin; if (reward[rewardKeys[i]][j].remain < release) { release = reward[rewardKeys[i]][j].remain; } if (waitRelease[rewardKeys[i]] != 0) { waitRelease[rewardKeys[i]] += release; } else { waitRelease[rewardKeys[i]] = release; } if (historyTotal[rewardKeys[i]] != 0) { historyTotal[rewardKeys[i]] += release; } else { historyTotal[rewardKeys[i]] = release; } reward[rewardKeys[i]][j].remain = reward[rewardKeys[i]][j].remain - release; history[rewardKeys[i]].push( RewardHistory( release, sameCoinValue, fixMineCoin, coinPrice, block.timestamp ) ); _totalMineCnt += release; emit CoinReward( rewardKeys[i], release, coinPrice, sameCoinValue, fixMineCoin ); } } } function releaseCoin(address sender) public returns (uint256) { uint256 release = waitRelease[sender]; waitRelease[sender] = 0; _totalRemainCnt -= release; return release; } function getWaitReleaseCoin(address sender) public view returns (uint256) { return waitRelease[sender]; } function getRewardList(address sender) public view returns (RewardData[] memory) { return reward[sender]; } function getRewardAddressList() public view returns (address[] memory) { return rewardKeys; } function getHistory(address sender) public view returns (RewardHistory[] memory) { return history[sender]; } function getHistoryMineTotal(address sender) public view returns (uint256) { return historyTotal[sender]; } function getTotalMineCnt() external view returns (uint256) { return _totalMineCnt; } function getTotalRemainCnt() external view returns (uint256) { return _totalRemainCnt; } }

